parameters.description:
=Llamar para avisar al asesor sobre su cliente en dos casos: (1) consultó un link de una propiedad de su cartera, o (2) quiere visitar una propiedad y dejó su disponibilidad para que el asesor coordine.

agency_id:{{ $('Set valores').item.json.body.lead.agency_id }}
conversation_id:{{ $('Set valores').item.json.body.conversacion.conversation_id }}

parameters.jsCode:
// Armar_Memoria — construye el bloque MEMORIA DEL LEAD que antes se renderizaba
// con 30 expresiones fijas dentro del prompt.
//
// REGLAS DE PARIDAD (no romper):
//  - Los campos que en el prompt usaban `|| 'no registrado'` conservan esa semántica.
//  - Los booleanos usaban ternario: false es DATO ("no"), no ausencia.
//  - Los arrays usaban (arr || []).join(', ') || 'ninguno'.
//  - Se pasa por delante todo el json de Memoria Lead, por si algo lee $json.metricas.
//
// QUÉ CAMBIA: los campos sin dato ya no imprimen una línea "no registrado" cada uno.
// Los del MÍNIMO pasan a una lista corta de PENDIENTES; los opcionales se omiten.
// Siempre visibles (porque su ausencia dispara conducta): los 11 del MÍNIMO
// (como sabidos o como pendientes), criterios innegociables, email y todo ESTADO.

const salida = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const m = (j.metricas && typeof j.metricas === 'object') ? j.metricas : {};

  // --- helpers que replican la semántica vieja ---
  const txt = (v) => (v === null || v === undefined || v === '' ? '' : String(v).trim());
  const orNo = (v) => txt(v) || 'no registrado';                    // equivalente a `|| 'no registrado'`
  const bool3 = (v) => (v === true ? 'sí' : (v === false ? 'no' : 'no registrado'));
  const lista = (v, vacio) => ((Array.isArray(v) ? v : []).join(', ') || vacio);
  const tiene = (v) => txt(v) !== '' && txt(v) !== 'no registrado';
  const tieneBool = (v) => v === true || v === false;

  // --- tipo de operación: decide si los 2 campos de compra aplican ---
  const op = txt(m.tipo_operacion).toLowerCase();
  const esCompra = /compr|venta/.test(op);
  const esAlquilerOInversion = /alquil|inversi|renta|temporar/.test(op);
  // si la operación todavía no se sabe, los tratamos como pendientes igual

  // --- los 11 del MÍNIMO, en ORDEN DE PRIORIDAD ---
  const presupuesto = tiene(m.presupuesto_max)
    ? (txt(m.presupuesto_max) + (txt(m.moneda_presupuesto) ? ' ' + txt(m.moneda_presupuesto) : ''))
    : '';

  const MINIMO = [
    { et: 'Nombre',                                  val: txt(m.nombre),               ok: tiene(m.nombre) },
    { et: 'Tipo de operación',                       val: txt(m.tipo_operacion),       ok: tiene(m.tipo_operacion) },
    { et: 'Tipo de propiedad',                       val: txt(m.tipo_propiedad),       ok: tiene(m.tipo_propiedad) },
    { et: 'Zona',                                    val: txt(m.zona),                 ok: tiene(m.zona) },
    { et: 'Ambientes',                               val: txt(m.ambientes_buscados),   ok: tiene(m.ambientes_buscados) },
    { et: 'Presupuesto',                             val: presupuesto,                 ok: presupuesto !== '' },
    { et: 'Urgencia',                                val: txt(m.urgencia),             ok: tiene(m.urgencia) },
    { et: 'Necesita vender para comprar',            val: bool3(m.necesita_vender_para_comprar), ok: tieneBool(m.necesita_vender_para_comprar), soloCompra: true },
    { et: 'Crédito · etapa del trámite',             val: txt(m.etapa_credito),        ok: tiene(m.etapa_credito), soloCompra: true },
    { et: 'Acompañado por otro asesor/inmobiliaria', val: txt(m.acompanado_asesor),    ok: tiene(m.acompanado_asesor) },
    { et: 'Hace cuánto busca',                       val: txt(m.hace_cuanto_busca),    ok: tiene(m.hace_cuanto_busca) },
  ];

  const sabidos = [];
  const pendientes = [];
  const noAplican = [];
  for (const c of MINIMO) {
    // si el campo TIENE dato se muestra siempre, aunque la operacion no sea compra:
    // "no aplica" significa que no hace falta preguntarlo, nunca que se oculte un dato real
    if (c.ok) { sabidos.push(`${c.et}: ${c.val}`); continue; }
    if (c.soloCompra && esAlquilerOInversion) { noAplican.push(c.et); continue; }
    pendientes.push(c.et + (c.soloCompra && !esCompra ? ' (solo si es compra)' : ''));
  }

  // --- opcionales: SOLO si tienen dato ---
  const opcionales = [];
  const addOpt = (et, v) => { if (tiene(v)) opcionales.push(`${et}: ${txt(v)}`); };
  const addOptBool = (et, v) => { if (tieneBool(v)) opcionales.push(`${et}: ${bool3(v)}`); };
  addOpt('Composición familiar', m.composicion_familiar);
  addOpt('Motivo de búsqueda', m.motivo_busqueda);
  addOpt('Superficie mínima (m²)', m.superficie_min_m2);
  addOpt('Crédito · banco', m.banco_credito);
  addOptBool('Crédito · preaprobado', m.tiene_preaprobacion_credito);
  addOptBool('Le interesa que sea apto crédito', m.apto_credito);
  addOpt('Experiencia compradora', m.experiencia_compradora);
  addOptBool('Es inversor', m.es_inversor);

  // --- NIVEL 3: solo lo que tenga contenido ---
  const n3 = [];
  const addN3 = (et, arr) => { const s = (Array.isArray(arr) ? arr : []).join(', '); if (s) n3.push(`${et}: ${s}`); };
  addN3('Lo que valora', m.intereses);
  addN3('Necesidades concretas', m.necesidades);
  addN3('Amenities que consultó', m.amenities_consultados);
  addN3('Servicios que consultó', m.servicios_consultados);
  addN3('Cercanías que le importan', m.lugares_cercanos_buscados);
  addN3('Características que consultó', m.caracteristicas_propiedad);

  // --- ESTADO: siempre completo, su ausencia dispara conducta ---
  const mostradas = (Array.isArray(m.propiedades_mostradas) ? m.propiedades_mostradas : [])
    .map(p => (p && (p.direccion || p.url)) ? `${p.direccion || 's/d'} (${p.url || 's/d'})` : null)
    .filter(Boolean).join(' | ') || 'ninguna';

  // --- armado del bloque (formato compacto: separadores en vez de una linea por campo) ---
  const L = [];
  L.push('YA SABEMOS (no lo repreguntes, ni en otra sesion):');
  L.push(sabidos.length ? sabidos.join(' · ') : 'nada todavia de este cliente.');

  L.push('');
  L.push('FALTA DEL MINIMO — tu proxima pregunta es la PRIMERA de esta lista (una por mensaje):');
  if (pendientes.length) L.push(pendientes.map((p,i)=>`${i+1}. ${p}`).join('\n'));
  else L.push('nada pendiente: los 11 ya estan. No sigas preguntando de esta lista.');
  if (noAplican.length) L.push(`(no aplican por ser ${txt(m.tipo_operacion)}, contalos cubiertos: ${noAplican.join(', ')})`);

  L.push('');
  const otros = [`Criterios innegociables: ${lista(m.criterios_duros,'ninguno')}`,
                 `Email: ${orNo(m.email)}`].concat(opcionales);
  L.push('OTROS: ' + otros.join(' · '));
  if (n3.length) L.push('NIVEL 3 (para elegir propiedades, no para preguntar): ' + n3.join(' · '));

  L.push('ESTADO: ' + [
    `Propiedad de interes: ${tiene(m.propiedad_interes) ? txt(m.propiedad_interes) : 'ninguna'}`,
    `Link pendiente: ${tiene(m.link_compartido) ? txt(m.link_compartido) : 'ninguno'}`,
    `Etapa: ${txt(m.etapa) || 'inicio'}`,
    `Calificacion: ${txt(m.calificacion_completitud) || '0'}/11 (${txt(m.calificado) || 'no'}) [informativa, va un turno atrasada: NO es umbral]`
  ].join(' · '));
  L.push(`YA MOSTRADAS (NO las repitas, controla por enlace): ${mostradas}`);

  // pasa por delante todo lo de Memoria Lead + el texto armado
  salida.push({ json: Object.assign({}, j, { memoria_texto: L.join('\n') }) });
}

return salida;

